std::string jsonStringLiteral(const std::string& value) {
    std::string escaped;
    escaped.reserve(value.size() + 2);
    for (const unsigned char ch : value) {
        switch (ch) {
            case '\\':
                escaped += "\\\\";
                break;
            case '"':
                escaped += "\\\"";
                break;
            case '\b':
                escaped += "\\b";
                break;
            case '\f':
                escaped += "\\f";
                break;
            case '\n':
                escaped += "\\n";
                break;
            case '\r':
                escaped += "\\r";
                break;
            case '\t':
                escaped += "\\t";
                break;
            default:
                if (ch < 0x20) {
                    char buffer[7];
                    std::snprintf(buffer, sizeof(buffer), "\\u%04x", ch);
                    escaped += buffer;
                } else {
                    escaped.push_back(static_cast<char>(ch));
                }
                break;
        }
    }
    return escaped;
}

std::string sanitizeSourceUrl(const std::string& value) {
    std::string sanitized = value.empty() ? "<embedded-user-script.js>" : value;
    for (char& ch : sanitized) {
        if (ch == '\r' || ch == '\n') {
            ch = ' ';
        }
    }
    return sanitized;
}

std::string buildEmbeddedModuleSourcesLiteral(const std::vector<std::pair<std::string, std::string>>& moduleSources) {
    std::string literal = "{";
    bool first = true;
    for (const auto& moduleSource : moduleSources) {
        if (!first) {
            literal += ",";
        }
        first = false;
        literal += "\"";
        literal += jsonStringLiteral(moduleSource.first);
        literal += "\":{source:\"";
        literal += jsonStringLiteral(moduleSource.second);
        literal += "\",sourceURL:\"";
        literal += jsonStringLiteral(sanitizeSourceUrl(moduleSource.first));
        literal += "\"}";
    }
    literal += "}";
    return literal;
}

std::string buildEmbeddedStringSetLiteral(const std::vector<std::string>& values) {
    std::string literal = "{";
    bool first = true;
    for (const std::string& value : values) {
        if (!first) {
            literal += ",";
        }
        first = false;
        literal += "\"";
        literal += jsonStringLiteral(value);
        literal += "\":true";
    }
    literal += "}";
    return literal;
}

